window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[73]={"id":"073","numero":73,"titre":"Techniques psychothérapeutiques","objectifs":[{"id":"73-1","rang":"A","rubrique":"Définition","titre":"Connaître la définition du terme psychothérapie","contenu":"<div class=\"notion-course\"><p>Une <strong><span>psychothérapie</span></strong> désigne « <em>toute utilisation de <span>moyens psychologiques</span> pour traiter un trouble psychiatrique ou pour tout autre problème entraînant une <span>souffrance</span> ou une <span>détresse psychologique</span></em> ».</p>\n      <p>Son <strong>but</strong> est de favoriser chez le sujet des <strong>changements significatifs</strong> dans son fonctionnement <span>cognitif</span>, <span>émotionnel</span> ou <span>comportemental</span>, dans son <span>système interpersonnel</span>, dans sa <span>personnalité</span> ou dans son <span>état de santé</span>.</p>\n      <table>\n        <thead><tr><th>Caractéristique</th><th>Détail</th></tr></thead>\n        <tbody>\n          <tr><td><span>Place</span></td><td>Utilisée <strong>seule</strong> ou associée à une <span>pharmacothérapie</span> et/ou à une <span>sociothérapie</span></td></tr>\n          <tr><td><span>Demande</span></td><td>Implique généralement une <strong>demande de soin et de changement</strong> et l'<strong>engagement</strong> du <span class=\"nc-green_bg\">patient</span></td></tr>\n          <tr><td><span>Cadre</span></td><td>Fonctionne avec un <strong>cadre</strong> : objectif(s) thérapeutique(s) ; nombre de séances ; durée</td></tr>\n          <tr><td><span>Moyens</span></td><td>Échange verbal ; relation thérapeute-<span class=\"nc-green_bg\">patient</span> ; réflexion ; suggestion ; apprentissage de techniques spécifiques</td></tr>\n          <tr><td><span>Visée</span></td><td>Selon la technique : développer des capacités présentes ; modifier des schémas de pensée ; limiter <span>les</span> conséquences négatives de désordres</td></tr>\n          <tr><td><span>Alliance</span></td><td><strong>Toujours</strong> via une <span>relation thérapeutique de qualité (alliance)</span> basée sur l'<span>empathie</span></td></tr>\n        </tbody>\n      </table>\n      <p>La psychothérapie implique <strong>généralement</strong> une demande du <span class=\"nc-green_bg\">patient</span> — mais pas toujours :</p>\n      <ul>\n        <li>Il existe des psychothérapies destinées aux <strong>parents</strong> pour améliorer <span>les</span> symptômes de leur <span>enfant</span> — programmes d'<span>entraînement aux habiletés parentales (PEHP)</span>, guidances parentales structurées.</li>\n        <li>Il existe des psychothérapies pour des personnes qui <strong>ne formulent pas de demande</strong> formelle — ex. <span>thérapies comportementales</span> dans <span>les</span> troubles du développement intellectuel, reposant sur des adaptations de l'environnement.</li>\n        <li>La cible du traitement est parfois un <span>groupe familial</span> ou une <span>dyade</span> (thérapies parent-enfant).</li>\n      </ul>\n      <p>Indications globales : la <strong>majorité des troubles psychiatriques</strong> et <span class=\"nc-brown_bg\">certains troubles non psychiatriques</span>.</p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 74 — Psychotropes</em></p></div><details><summary>Sources et compléments</summary><p>Relecture du 14 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d94181cb96eaf9cb347e93a5?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Techniques psychothérapeutiques (73)</a></li><li><a href=\"https://www.asso-aesp.fr/wp-content/uploads/2024/04/EDN-Psychiatrie-et-addictologie-4ed-bd.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNUP–AESP–CUNEA · Référentiel de psychiatrie et addictologie, 4e édition (2024)</a></li></ul><p></p></details><details data-lisa-review=\"20261014\"><summary>Situations de départ LiSA vérifiées</summary><p>Attendus consultés sur LiSA 2026 le 14 octobre 2026, reformulés pour la révision.</p><ul><li><a href=\"https://livret.uness.fr/lisa/2026/Anxi%C3%A9t%C3%A9_SDD-116\" target=\"_blank\" rel=\"noopener noreferrer\">SDD 116 · Anxiété</a><ul><li>Retracer l’histoire, caractériser les symptômes et leur retentissement ; rechercher dépression, suicide et addictions.</li><li>Discuter traitement de fond, suivi et avis psychiatrique ; prévenir le mésusage des benzodiazépines.</li></ul></li><li><a href=\"https://livret.uness.fr/lisa/2026/Consultation_de_suivi_et_traitement_de_fond_d%27un_patient_souffrant_d%27un_trouble_psychiatrique_chronique_(hors_d%C3%A9pression)_SDD-269\" target=\"_blank\" rel=\"noopener noreferrer\">SDD 269 · Suivi et traitement de fond d’un trouble psychiatrique chronique hors dépression</a><ul><li>Réévaluer décompensation, risque suicidaire, comorbidités, autonomie et insertion ; surveiller les psychotropes et leur observance.</li><li>Expliquer les psychothérapies et coordonner les soins ; la valorisation du stage inclut réhabilitation, remédiation cognitive et démarches MDPH.</li></ul></li><li><a href=\"https://livret.uness.fr/lisa/2026/Consultation_de_suivi_et_traitement_de_fond_d%27un_patient_d%C3%A9pressif_SDD-288\" target=\"_blank\" rel=\"noopener noreferrer\">SDD 288 · Suivi et traitement de fond d’un patient dépressif</a><ul><li>Suivre les symptômes, le fonctionnement, le risque suicidaire, les comorbidités et l’observance.</li><li>Informer sur antidépresseur et psychothérapie ; réévaluer les sédatifs et les causes d’une réponse insuffisante.</li></ul></li></ul><p>Les liens ciblent les compétences pertinentes pour cet item ; ils ne signifient pas que la fiche couvre à elle seule toute la situation de départ.</p></details>","frequence":0},{"id":"73-2","rang":"A","rubrique":"Définition","titre":"Connaître ce qui relève de la psychothérapie ; ce qui s’en rapproche ; ce qui n’en est pas","contenu":"<div class=\"notion-course\"><p>Une psychothérapie n'est <strong>pas une simple conversation</strong> : pour être reconnue comme telle, une méthode d'intervention psychologique doit remplir <strong>plusieurs conditions</strong>. Il faut aussi la distinguer de pratiques qui s'en <span>rapprochent</span> ou qui <span>n'en relèvent pas</span>.</p>\n      <table>\n        <thead><tr><th>Catégorie</th><th>Critères / exemples</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span>Est une psychothérapie</span><br>(5 conditions cumulatives)</td>\n            <td>\n              <strong>Théorie :</strong> <span class=\"nc-blue_bg\">fondée sur une </span><span><span class=\"nc-blue_bg\">théorie scientifique reconnue</span></span><br>\n              <strong>Technique :</strong> <span><span class=\"nc-blue_bg\">technique codifiée</span></span> (outils psychothérapeutiques spécifiques)<br>\n              <strong>Indications :</strong> <span class=\"nc-yellow_bg\">indications </span><strong><span class=\"nc-yellow_bg\">clairement établies</span></strong><br>\n              <strong>Évaluation :</strong> effets <span>favorables et défavorables</span> qui peuvent être <strong>évalués</strong><br>\n              <strong>Intervenants :</strong> <span class=\"nc-blue_bg\">pratiquée par des intervenants </span><strong><span class=\"nc-blue_bg\">formés et compétents</span></strong>\n            </td>\n          </tr>\n          <tr>\n            <td><span>S'en rapproche</span><br>(sans en être une)</td>\n            <td>La <strong><span>relation d'aide empathique</span></strong> : relation soignant-<span class=\"nc-green_bg\">patient</span> basée sur le <span>respect</span> et l'<span>empathie</span>, mais <strong>sans <span class=\"nc-blue_bg\">formation spécifique</span></strong><span class=\"nc-blue_bg\"> à la psychothérapie</span></td>\n          </tr>\n          <tr>\n            <td><span>N'en est pas</span></td>\n            <td>Coaching non thérapeutique, soutien informel des proches, pratiques sans méthode ni indications établies. La réglementation du titre constitue une question distincte.</td>\n          </tr>\n        </tbody>\n      </table></div><details><summary>Sources et compléments</summary><p>Relecture du 14 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d94181cb96eaf9cb347e93a5?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Techniques psychothérapeutiques (73)</a></li><li><a href=\"https://www.asso-aesp.fr/wp-content/uploads/2024/04/EDN-Psychiatrie-et-addictologie-4ed-bd.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNUP–AESP–CUNEA · Référentiel de psychiatrie et addictologie, 4e édition (2024)</a></li></ul><p></p></details>","frequence":0},{"id":"73-3","rang":"B","rubrique":"Définition","titre":"Connaître les aspects réglementaires","contenu":"<div class=\"notion-course\"><h4>Titre et formation</h4><p>L’usage du <span class=\"nc-yellow_bg\">titre de psychothérapeute est</span> <span class=\"nc-yellow_bg nc-bold\">réglementé</span>. Le socle est une formation en psychopathologie clinique d’au moins 400 heures et un stage d’au moins cinq mois ; des dispenses totales ou partielles existent selon le diplôme et les stages déjà effectués. Les psychiatres sont dispensés ; la situation des psychologues dépend des conditions prévues par le décret. Une simple formation privée à une technique ne suffit pas à obtenir le titre.</p><p>L’inscription réglementaire doit être accomplie : dispense de formation ne signifie pas inscription automatique. Psychothérapeute, <span class=\"nc-blue_bg\">psychologue</span>, <span class=\"nc-blue_bg\">psychiatre</span> et psychanalyste ne sont pas des titres interchangeables.</p><h4>Accès et remboursement</h4><ul><li>En secteur public : CMP et structures de soins selon leur organisation.</li><li><span class=\"nc-blue_bg\">Psychiatre</span> libéral : remboursement d’une consultation médicale selon parcours, conventionnement et situation ; l’adressage ne rend pas systématiquement la consultation intégralement remboursée.</li><li><span class=\"nc-blue_bg\">Psychologue</span> libéral : Mon soutien psy permet un accès direct à un professionnel partenaire pour les situations éligibles. Jusqu’à 12 séances par année civile, à 50 €, prises en charge à 60 % par l’Assurance maladie, complément selon couverture ou exonération.</li><li>Exception actuelle : séances non plafonnées pour certains mineurs en ALD, hors ALD 23 et critères de non-inclusion, lorsqu’elles s’inscrivent dans le protocole de soins.</li><li>Crise suicidaire, trouble sévère ou urgence : orienter vers les soins adaptés ; ce dispositif ne remplace pas la psychiatrie spécialisée.</li></ul></div><details><summary>Sources et compléments</summary><p>Relecture du 14 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d94181cb96eaf9cb347e93a5?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Techniques psychothérapeutiques (73)</a></li><li><a href=\"https://www.asso-aesp.fr/wp-content/uploads/2024/04/EDN-Psychiatrie-et-addictologie-4ed-bd.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNUP–AESP–CUNEA · Référentiel de psychiatrie et addictologie, 4e édition (2024)</a></li><li><a href=\"https://www.legifrance.gouv.fr/loda/id/JORFTEXT000022244482/\" target=\"_blank\" rel=\"noopener noreferrer\">Légifrance · Décret du 20 mai 2010, titre de psychothérapeute</a></li><li><a href=\"https://www.ameli.fr/assure/remboursements/rembourse/remboursement-seance-psychologue-mon-soutien-psy\" target=\"_blank\" rel=\"noopener noreferrer\">Assurance maladie · Mon soutien psy</a></li></ul><p>Mise à jour des dispenses, de l’inscription et du remboursement ; ne pas assimiler psychologue libéral et consultation médicale.</p></details>","frequence":0},{"id":"73-4","rang":"A","rubrique":"Définition","titre":"Connaître les principaux courants psychothérapeutiques","contenu":"<div class=\"notion-course\"><p>Il existe de <strong>nombreuses formes de psychothérapies</strong>, reposant chacune sur un <span>courant théorique</span> et une <span>technique propre</span>. Elles se regroupent en <strong>trois grands courants de pensée</strong>.</p>\n      <table>\n        <thead><tr><th>Courant</th><th>Hypothèse / idée directrice</th></tr></thead>\n        <tbody>\n          <tr><td><span>Cognitivo-comportemental</span></td><td><span>Les</span> symptômes sont des réponses comportementales et cognitives <strong>apprises</strong> ; on les modifie par apprentissage</td></tr>\n          <tr><td><span>Psychodynamique (analytique)</span></td><td><span>Les</span> symptômes sont liés à des <span>conflits inconscients</span> non résolus</td></tr>\n          <tr><td><span>Systémique</span></td><td>Le symptôme s'inscrit dans un <span>système</span> (famille, couple) en interaction permanente</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>À retenir.</strong> Ces courants ne sont <strong>pas antinomiques</strong> : chacun a sa propre hypothèse du fonctionnement du psychisme et aborde le soin <strong>de manière différente</strong>.</div>\n      <p><span>Les</span> principales <strong>techniques</strong> rattachées à ces courants — détaillées dans les objectifs suivants :</p>\n      <table>\n        <thead><tr><th>Technique</th><th>Repère</th></tr></thead>\n        <tbody>\n          <tr><td><span><span class=\"nc-yellow_bg\">Psychothérapie de soutien</span></span></td><td>Psychothérapie de <strong>1er niveau</strong>, base commune à toutes <span>les</span> autres</td></tr>\n          <tr><td><span>Thérapies cognitivo-comportementales (TCC)</span></td><td>Courant cognitivo-comportemental ; acquisition de compétences psychologiques</td></tr>\n          <tr><td><span>Psychothérapie psychodynamique / psychanalytique</span></td><td>Courant analytique ; travaux de <strong>S. Freud</strong> — conflits inconscients depuis l'enfance</td></tr>\n          <tr><td><span>Thérapie familiale / systémique</span></td><td>Courant systémique ; la famille / le couple comme système, « <span class=\"nc-green_bg\">patient</span>-désigné »</td></tr>\n          <tr><td><span>Remédiation cognitive</span></td><td>Héritée de la neuropsychologie et des TCC ; amélioration du fonctionnement cognitif</td></tr>\n          <tr><td><span><span class=\"nc-yellow_bg\">Éducation thérapeutique</span></span></td><td>Transmission de connaissances sur la maladie et son traitement</td></tr>\n        </tbody>\n      </table></div><details><summary>Sources et compléments</summary><p>Relecture du 14 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d94181cb96eaf9cb347e93a5?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Techniques psychothérapeutiques (73)</a></li><li><a href=\"https://www.asso-aesp.fr/wp-content/uploads/2024/04/EDN-Psychiatrie-et-addictologie-4ed-bd.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNUP–AESP–CUNEA · Référentiel de psychiatrie et addictologie, 4e édition (2024)</a></li></ul><p></p></details>","frequence":0},{"id":"73-5","rang":"B","rubrique":"Prise en charge","titre":"Connaître les principes communs à toutes les psychothérapies","contenu":"<div class=\"notion-course\"><p>Au-delà de leur diversité, toutes <span>les</span> psychothérapies partagent un même socle. Chacune comporte un <strong><span>cadre</span></strong> avec ses règles : définition d'un <strong>objectif thérapeutique</strong>, du <strong>nombre de séances</strong> et de leur <strong>durée</strong>.</p>\n      <p>Cinq <strong>dimensions communes</strong> à toutes <span>les</span> psychothérapies ont été définies :</p>\n      <table>\n        <thead><tr><th>Dimension commune</th><th>Contenu</th></tr></thead>\n        <tbody>\n          <tr><td><span>Cadre thérapeutique</span></td><td>Cadre <strong>stable</strong> et <strong>sécurisant</strong></td></tr>\n          <tr><td><span>Relation thérapeutique</span></td><td>Relation de <strong>qualité</strong>, basée sur l'<span>empathie</span> et l'expression des émotions douloureuses jusqu'alors évitées</td></tr>\n          <tr><td><span>Implication</span></td><td>Processus d'<strong>implication (engagement)</strong> du <span class=\"nc-green_bg\">patient</span></td></tr>\n          <tr><td><span>Intervention</span></td><td>Processus d'<strong>intervention</strong> offrant un cadre explicatif inspirant</td></tr>\n          <tr><td><span>Apprentissage</span></td><td>Processus d'<strong>apprentissage cognitif et affectif</strong> : accroissement de l'<span>espoir</span>, maîtrise, acquisition de nouveaux comportements</td></tr>\n        </tbody>\n      </table>\n      <p><span>Les</span> <strong>moyens utilisés</strong> sont divers et communs à l'ensemble des techniques : <span>échange verbal</span>, utilisation de la <span>relation thérapeute-<span class=\"nc-green_bg\">patient</span></span>, <span>réflexion</span>, <span>suggestion</span>, <span>apprentissage de techniques spécifiques</span>.</p></div><details><summary>Sources et compléments</summary><p>Relecture du 14 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d94181cb96eaf9cb347e93a5?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Techniques psychothérapeutiques (73)</a></li><li><a href=\"https://www.asso-aesp.fr/wp-content/uploads/2024/04/EDN-Psychiatrie-et-addictologie-4ed-bd.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNUP–AESP–CUNEA · Référentiel de psychiatrie et addictologie, 4e édition (2024)</a></li></ul><p></p></details>","frequence":0},{"id":"73-6","rang":"B","rubrique":"Prise en charge","titre":"Connaître la psychothérapie de soutien","contenu":"<div class=\"notion-course\"><p>La <strong><span><span class=\"nc-yellow_bg\">psychothérapie de soutien</span></span></strong> est la psychothérapie de <strong>1er niveau</strong> : c'est la <strong>base commune</strong> sur laquelle se construisent <span>les</span> autres, <strong>la plus utilisée</strong> et <strong>la moins théorisée</strong>.</p>\n      <table>\n        <thead><tr><th>Axe</th><th>Contenu</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span>Principes théoriques</span></td>\n            <td>\n              <strong>Théorie composite :</strong> emprunte aux théories <span>analytique</span> et <span>cognitivo-comportementale</span>, à l'expérience humaine et professionnelle, aux ressources relationnelles<br>\n              <strong>Visée :</strong> accompagner le <span class=\"nc-green_bg\">patient</span> face à une <span>situation de vie difficile / stressante</span> — <span>annonce</span> d'une <span>maladie grave</span> ; <span>traumatisme</span> ; <span>deuil</span> ; <span>anxiété réactionnelle</span> ; accompagnement de troubles psychiatriques en <span>complément</span> d'autres approches\n            </td>\n          </tr>\n          <tr>\n            <td><span>Objectifs</span></td>\n            <td>\n              Faciliter l'<span>expression d'émotions douloureuses</span><br>\n              Favoriser <span>les</span> <span>stratégies d'ajustement</span> face au stress<br>\n              <span>Donner de l'espoir</span><br>\n              Améliorer l'<span>estime de soi</span> et le <span>sentiment d'efficacité personnelle</span>\n            </td>\n          </tr>\n          <tr>\n            <td><span>Modalités pratiques</span></td>\n            <td>\n              <strong>Repérer et structurer la demande</strong> du <span class=\"nc-green_bg\">patient</span><br>\n              <span>Écoute attentive, empathique, compréhensive</span> : valider <span>les</span> ressentis en nommant et clarifiant le contenu des émotions<br>\n              <strong>Dépister les résistances</strong><br>\n              Soutenir et renforcer le sentiment de liberté et d'efficacité personnelle : <span>réassurer</span>, encourager, valoriser, conseiller\n            </td>\n          </tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 144 — Deuil</em></p></div><details><summary>Sources et compléments</summary><p>Relecture du 14 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d94181cb96eaf9cb347e93a5?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Techniques psychothérapeutiques (73)</a></li><li><a href=\"https://www.asso-aesp.fr/wp-content/uploads/2024/04/EDN-Psychiatrie-et-addictologie-4ed-bd.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNUP–AESP–CUNEA · Référentiel de psychiatrie et addictologie, 4e édition (2024)</a></li></ul><p></p></details>","frequence":0},{"id":"73-7","rang":"B","rubrique":"Prise en charge","titre":"Connaître les thérapies cognitivo-comportementales","contenu":"<div class=\"notion-course\"><p><span>Les</span> <strong><span>thérapies cognitivo-comportementales (TCC)</span></strong> sont des psychothérapies <strong>principalement verbales</strong> visant à faire acquérir au <span class=\"nc-green_bg\">patient</span> des <strong>compétences psychologiques</strong> pour mieux faire face à ses problèmes. Elles appartiennent aux <span>thérapies brèves</span>.</p>\n      <div class=\"callout callout-info\"><strong>Postulat.</strong> <span>Les</span> symptômes sont des <strong>réponses comportementales et/ou cognitives dysfonctionnelles</strong> : pensées erronées « <span>automatiques</span> », <span>évitement</span> d'une situation anxiogène, troubles constitués (<span class=\"nc-orange_bg\">phobie</span>, trouble panique). On repère les situations à problèmes, les pensées et émotions reliées, puis on élabore des <strong>stratégies alternatives</strong>. Le <span>conditionnement</span> (apprentissage social + renforcement) permet de modifier la réponse à un stimulus.</div>\n      <p><span>Les</span> TCC reposent sur un corpus théorique commun et ont connu <strong><span>3 évolutions</span> successives</strong> :</p>\n      <table>\n        <thead><tr><th>Vague</th><th>Période</th><th>Idée directrice</th></tr></thead>\n        <tbody>\n          <tr><td><span>1ʳᵉ — Comportementale</span></td><td><span>Début 20ᵉ s.</span></td><td>Théories du <span>conditionnement classique et opérant</span> : comment <span>les</span> comportements sont appris, comment l'environnement les influence</td></tr>\n          <tr><td><span>2ᵉ — Révolution cognitive</span></td><td><span>1960</span></td><td><span>Schémas cognitifs</span> <span>acquis</span> par apprentissage → <span>pensées automatiques</span> qui guident le comportement</td></tr>\n          <tr><td><span>3ᵉ — Vague émotionnelle</span></td><td><span>2000</span></td><td>Accent sur l'<span>acceptation</span> et la <span>pleine conscience</span></td></tr>\n        </tbody>\n      </table>\n      <p>Le déroulement type : objectifs déterminés <strong>avec le <span class=\"nc-green_bg\">patient</span></strong>, <span>analyse fonctionnelle</span> de la problématique, <strong>contrat thérapeutique</strong>, évaluation objective et partagée de l'efficacité (échelles et questionnaires).</p>\n      <p><span>Les</span> TCC mobilisent <strong>trois méthodes</strong> :</p>\n      <table>\n        <thead><tr><th>Méthode</th><th>Techniques</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span>Comportementale</span></td>\n            <td>\n              <span>Désensibilisation</span> : confrontation <strong>en imagination</strong> au stimulus anxiogène<br>\n              <span>Exposition</span> : confrontation <strong>in vivo</strong> graduée, avec « <span>modeling</span> » participatif (le thérapeute montre de nouveaux comportements)<br>\n              <span><span class=\"nc-pink_bg\">Immersion (« flooding »)</span></span> : <span class=\"nc-pink_bg\">confrontation directe, </span><strong><span class=\"nc-pink_bg\">non graduée</span></strong><span class=\"nc-pink_bg\">, à un stimulus anxiogène maximal</span>\n            </td>\n          </tr>\n          <tr>\n            <td><span>Cognitive</span></td>\n            <td>\n              Identification et <strong>remise en question des pensées automatiques</strong> et des schémas cognitifs<br>\n              <span>Thérapie rationnelle d'Ellis</span> et <span>méthode de Beck</span> : étude des biais de raisonnement (surgénéralisation, pensée dichotomique, conclusions arbitraires)<br>\n              <span><span class=\"nc-blue_bg\">Affirmation de soi</span></span> ; <span class=\"nc-blue_bg\">développement des </span><span><span class=\"nc-blue_bg\">compétences sociales</span></span>\n            </td>\n          </tr>\n          <tr>\n            <td><span>Émotionnelle</span></td>\n            <td>\n              <span>Acceptation et engagement</span> dans des changements en accord avec ses valeurs<br>\n              <span class=\"nc-green_bg\">Techniques de </span><span><span class=\"nc-green_bg\">tolérance à la détresse</span></span><span class=\"nc-green_bg\"> et de gestion des émotions</span><br>\n              <span><span class=\"nc-green_bg\">Méditation de pleine conscience</span></span>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n      <p>Exemples d’approches : ACT, <span class=\"nc-yellow_bg\">thérapie comportementale dialectique</span>, MBCT, réduction du stress par pleine conscience et <span class=\"nc-yellow_bg\">activation comportementale</span>. Leur indication et leur niveau de preuve dépendent du trouble et de l’objectif ; aucune efficacité universelle ne doit être déduite de cette liste.</p>\n      <p><strong>Chez l'enfant et l'adolescent</strong> : <span>les</span> TCC s'adressent soit à l'enfant, soit aux parents, soit via des programmes mixtes ; il s'agit surtout d'apprendre des stratégies (<span>habiletés sociales</span>, <span><span class=\"nc-blue_bg\">affirmation de soi</span></span>, capacités d'<span>inhibition</span>) par apprentissage, imitation, renforcement positif, exposition, jeux de rôle et exercices à la maison.</p>\n      <div class=\"callout callout-warn\"><strong>Piège classique.</strong> La <span>restructuration cognitive</span> est une <strong>TCC</strong> (méthode cognitive) — à ne <strong>pas confondre</strong> avec la <span>remédiation cognitive</span> (objectif suivant). <span>Confusion</span> déjà tombée en annale.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 63 — Trouble schizophrénique · 64 — <span>Trouble bipolaire</span> · 66 — Trouble dépressif · 66 — Trouble anxieux</em></p><div class=\"callout\"><p>L’exposition est planifiée, expliquée et consentie ; elle peut être in vivo, imaginaire ou intéroceptive selon le trouble. Elle ne se réduit pas à forcer une confrontation maximale.</p></div></div><details><summary>Sources et compléments</summary><p>Relecture du 14 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d94181cb96eaf9cb347e93a5?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Techniques psychothérapeutiques (73)</a></li><li><a href=\"https://www.asso-aesp.fr/wp-content/uploads/2024/04/EDN-Psychiatrie-et-addictologie-4ed-bd.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNUP–AESP–CUNEA · Référentiel de psychiatrie et addictologie, 4e édition (2024)</a></li></ul><p></p></details>","frequence":1},{"id":"73-8","rang":"B","rubrique":"Prise en charge","titre":"Connaître la remédiation cognitive","contenu":"<div class=\"notion-course\"><p>La <strong><span>remédiation cognitive</span></strong> est une approche permettant d'<strong>améliorer le fonctionnement cognitif</strong>, par deux voies :</p>\n      <ul>\n        <li>Soit en <strong><span class=\"nc-yellow_bg\">entraînant </span><span><span class=\"nc-yellow_bg\">les</span></span><span class=\"nc-yellow_bg\"> fonctions déficitaires</span></strong> ;</li>\n        <li>Soit en permettant au <span class=\"nc-green_bg\">patient</span> d'<strong>acquérir des stratégies</strong> pour exploiter au mieux ses <span>fonctions résiduelles</span>.</li>\n      </ul>\n      <p>Elle est <strong>héritée de la neurologie, de la neuropsychologie et des TCC</strong> et se rapproche de techniques de <span>rééducation</span> ; elle s'inscrit dans <span>les</span> stratégies de prise en charge du <span>handicap</span> et la <span>réhabilitation psychosociale</span>.</p>\n      <p>Ses <strong>cibles</strong> sont <span>les</span> fonctions cognitives, classées en deux groupes :</p>\n      <table>\n        <thead><tr><th>Type d'altération cognitive</th><th>Fonctions concernées</th></tr></thead>\n        <tbody>\n          <tr><td><span>Non spécifiques</span><br>(ex. maladies neurologiques)</td><td><span><span class=\"nc-blue_bg\">Mémoire</span></span> ; <span><span class=\"nc-blue_bg\">fonctions exécutives</span></span> ; <span><span class=\"nc-blue_bg\">fonctions visuo-spatiales</span></span> ; <span><span class=\"nc-blue_bg\">attention</span></span><span class=\"nc-blue_bg\"> et vitesse de traitement de l'information</span></td></tr>\n          <tr><td><span>Spécifiques aux troubles psychiatriques</span></td><td><span><span class=\"nc-blue_bg\">Métacognition</span></span> (connaissance et conscience de son propre fonctionnement cognitif) ; <span><span class=\"nc-blue_bg\">cognition sociale</span></span> (processus cognitifs des interactions sociales)</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>Objectif.</strong> Il ne s'agit pas seulement d'augmenter <span>les</span> <strong>performances cognitives</strong> mais <span class=\"nc-green_bg\">surtout de </span><strong><span class=\"nc-green_bg\">réduire les répercussions</span></strong><span class=\"nc-green_bg\"> de ces altérations</span> et de diminuer le <span>handicap fonctionnel</span> — notamment chez les patients <span>schizophrènes</span>.</div>\n      <p><strong>Préalable indispensable</strong> : une <span>évaluation complète individuelle</span> — bilan <span>neuropsychologique</span> + évaluation de la <span><span class=\"nc-blue_bg\">cognition sociale</span></span>.</p>\n      <div class=\"callout callout-warn\"><strong>Mesure associée.</strong> <span>Les</span> <span class=\"nc-yellow_bg\">soins de remédiation n'ont </span><strong><span class=\"nc-yellow_bg\">que peu d'efficacité</span></strong><span class=\"nc-yellow_bg\"> s'ils ne sont pas associés à des actions de </span><span><span class=\"nc-yellow_bg\">réhabilitation</span></span> : un <strong><span class=\"nc-green nc-bold\">environnement stimulant</span></strong> dans lequel la personne peut exercer les compétences travaillées (ex. retour à l'emploi).</div>\n      <div class=\"callout callout-warn\"><strong>Piège classique.</strong> Ne pas confondre la <span>remédiation cognitive</span> avec la <span>restructuration cognitive</span>, qui est une <strong>TCC</strong>. <span>Confusion</span> déjà tombée en annale.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 63 — Trouble schizophrénique · 121 — Handicap psychique</em></p></div><details><summary>Sources et compléments</summary><p>Relecture du 14 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d94181cb96eaf9cb347e93a5?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Techniques psychothérapeutiques (73)</a></li><li><a href=\"https://www.asso-aesp.fr/wp-content/uploads/2024/04/EDN-Psychiatrie-et-addictologie-4ed-bd.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNUP–AESP–CUNEA · Référentiel de psychiatrie et addictologie, 4e édition (2024)</a></li></ul><p></p></details>","frequence":0},{"id":"73-9","rang":"B","rubrique":"Prise en charge","titre":"Connaître les principales indications","contenu":"<div class=\"notion-course\"><h4>Choisir une indication et évaluer le résultat</h4><p>Le choix dépend du diagnostic, de la gravité, du risque, des préférences, de l’accessibilité et de la formation du thérapeute. Une psychothérapie peut être seule ou associée aux médicaments et interventions sociales ; elle ne doit pas retarder le traitement d’une urgence.</p><table><thead><tr><th>Approche</th><th>Indications et repères</th></tr></thead><tbody><tr><td>Soutien</td><td>Accompagner la souffrance, mobiliser les ressources, soutenir l’alliance ; modalités adaptées à l’état clinique.</td></tr><tr><td>TCC</td><td>Troubles anxieux, TOC, dépression, insomnie, addictions et autres indications avec protocoles adaptés. Exposition avec prévention de la réponse dans le TOC ; thérapies centrées sur le traumatisme pour le TSPT.</td></tr><tr><td>Psychodynamique</td><td>Indication individualisée selon demande, fonctionnement et stabilité ; adapter ou différer une cure exploratoire intensive en décompensation aiguë.</td></tr><tr><td>Familiale / systémique</td><td>Mobiliser les interactions et ressources familiales, notamment dans les <span class=\"nc-orange_bg\">TCA</span> de l’adolescent ; ne pas attribuer mécaniquement la maladie à la famille.</td></tr><tr><td>Remédiation cognitive</td><td>Déficits objectivés avec retentissement et projet fonctionnel ; association à la réhabilitation.</td></tr><tr><td><span class=\"nc-yellow_bg\">Éducation thérapeutique</span></td><td>Compétences d’autosoins et adaptation dans les troubles chroniques ; complément des autres soins.</td></tr></tbody></table><ul><li>Évaluer régulièrement symptômes, fonctionnement, effets indésirables éventuels, adhésion et objectifs.</li><li>Le soutien et l’<span class=\"nc-yellow_bg\">éducation thérapeutique</span> doivent eux aussi être adaptés : éviter « toutes les techniques, pour tous les troubles, sans aucune réserve ».</li></ul></div><details><summary>Sources et compléments</summary><p>Relecture du 14 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d94181cb96eaf9cb347e93a5?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Techniques psychothérapeutiques (73)</a></li><li><a href=\"https://www.asso-aesp.fr/wp-content/uploads/2024/04/EDN-Psychiatrie-et-addictologie-4ed-bd.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNUP–AESP–CUNEA · Référentiel de psychiatrie et addictologie, 4e édition (2024)</a></li></ul><p></p></details>","frequence":0}],"astuces":[{"type":"piege","titre":"Ne pas confondre","contenu":"<div class=\"notion-course\"><p>Titre professionnel, méthode psychothérapeutique et remboursement sont trois questions distinctes.</p></div>"},{"type":"piege","titre":"TCC","contenu":"<div class=\"notion-course\"><p>Remédiation cognitive ≠ restructuration cognitive.</p></div>"}],"strategie":{"Démarche diagnostique":"<div class=\"notion-course\"><ul><li>Préciser plainte, trouble, gravité et objectifs.</li></ul></div>","Prise en charge":"<div class=\"notion-course\"><ul><li>Choisir ensemble une approche adaptée et évaluer son effet.</li><li>Orienter une urgence ou un trouble sévère vers une prise en charge appropriée.</li></ul></div>"},"cards":[{"i":"07fea6025e62","n":73,"o":"73-1","u":"Définition","t":"Connaître la définition du terme psychothérapie","q":"Quelle est la définition d'une psychothérapie selon les techniques psychothérapeutiques ?","a":"<div class=\"notion-course\"><p>Une psychothérapie désigne « toute utilisation de <strong>moyens psychologiques</strong> pour traiter un trouble psychiatrique ou pour tout autre problème entraînant une <strong>souffrance ou une détresse psychologique</strong> ».</p></div>"},{"i":"5ba65cfebf59","n":73,"o":"73-1","u":"Définition","t":"Connaître la définition du terme psychothérapie","q":"Quelles sont les caractéristiques générales qui définissent une psychothérapie ?","a":"<div class=\"notion-course\"><p>Les caractéristiques générales d'une psychothérapie incluent :</p><ul><li><strong>Place</strong> : Utilisée seule ou associée à une pharmacothérapie et/ou à une sociothérapie.</li><li><strong>Demande</strong> : Implique généralement une demande de soin et de changement, ainsi que l'engagement du <span class=\"nc-green_bg\">patient</span> (bien qu'il existe des exceptions, comme les PEHP ou les thérapies pour troubles du développement intellectuel).</li><li><strong>Cadre</strong> : Fonctionne avec un cadre défini (objectif(s) thérapeutique(s), nombre de séances, durée).</li><li><strong>Moyens</strong> : Utilise l'échange verbal, la relation thérapeute-<span class=\"nc-green_bg\">patient</span>, la réflexion, la suggestion, l'apprentissage de techniques spécifiques.</li><li><strong>Visée</strong> : Selon la technique, elle vise à développer des capacités, modifier des schémas de pensée, ou limiter les conséquences négatives de désordres.</li><li><strong>Alliance</strong> : Toujours via une relation thérapeutique de qualité (alliance) basée sur l'<strong>empathie</strong>.</li></ul></div>"},{"i":"899357be7587","n":73,"o":"73-1","u":"Définition","t":"Connaître la définition du terme psychothérapie","q":"Quel est le but d'une psychothérapie dans le contexte des techniques psychothérapeutiques ?","a":"<div class=\"notion-course\"><p>Le but d'une psychothérapie est de favoriser chez le sujet des <strong>changements significatifs</strong> dans son fonctionnement <ul><li>cognitif</li><li>émotionnel</li><li>comportemental</li><li>son système interpersonnel</li><li>sa personnalité</li><li>son état de santé</li></ul></p></div>"},{"i":"6b16d1134f13","n":73,"o":"73-2","u":"Définition","t":"Connaître ce qui relève de la psychothérapie ; ce qui s’en rapproche ; ce qui n’en est pas","q":"Quelles sont les 5 conditions cumulatives pour qu'une méthode d'intervention psychologique soit reconnue comme une psychothérapie ?","a":"<div class=\"notion-course\"><p>Pour être reconnue comme une psychothérapie, une méthode d'intervention psychologique doit remplir les 5 conditions cumulatives suivantes :</p><ul><li>Elle doit être <span class=\"nc-blue_bg\">fondée sur une </span><strong><span class=\"nc-blue_bg\">théorie scientifique reconnue</span></strong>.</li><li>La <strong>technique doit être codifiée</strong>, avec des outils psychothérapeutiques spécifiques.</li><li>Les <strong>indications doivent être clairement établies</strong>.</li><li>Les <strong>effets (favorables et défavorables)</strong> doivent pouvoir être <strong>évalués</strong>.</li><li>Elle doit être <span class=\"nc-blue_bg\">pratiquée par des </span><strong><span class=\"nc-blue_bg\">intervenants formés et compétents</span></strong>.</li></ul></div>"},{"i":"6d8c89c52f62","n":73,"o":"73-2","u":"Définition","t":"Connaître ce qui relève de la psychothérapie ; ce qui s’en rapproche ; ce qui n’en est pas","q":"Quelle pratique se rapproche de la psychothérapie sans en être une ?","a":"<div class=\"notion-course\"><p>La <strong>relation d'aide empathique</strong> se rapproche de la psychothérapie sans en être une. Il s'agit d'une relation soignant-<span class=\"nc-green_bg\">patient</span> basée sur le respect et l'empathie, mais elle ne requiert pas de <span class=\"nc-blue_bg\">formation spécifique à la psychothérapie</span>.</p></div>"},{"i":"a064da47acd5","n":73,"o":"73-2","u":"Définition","t":"Connaître ce qui relève de la psychothérapie ; ce qui s’en rapproche ; ce qui n’en est pas","q":"Quels exemples de pratiques ne sont pas considérées comme des psychothérapies ?","a":"<div class=\"notion-course\"><ul><li>Coaching non thérapeutique et soutien informel des proches.</li><li>La relation empathique seule ne suffit pas à définir une psychothérapie structurée.</li></ul></div>"},{"i":"0977bf65285c","n":73,"o":"73-4","u":"Définition","t":"Connaître les principaux courants psychothérapeutiques","q":"Quelle est la principale technique psychothérapeutique rattachée au courant psychodynamique/analytique ?","a":"<div class=\"notion-course\"><p>La principale technique rattachée au courant psychodynamique/analytique est la <strong>psychothérapie psychodynamique</strong> ou <strong>psychanalytique</strong>, héritée des travaux de S. Freud, et axée sur les conflits inconscients de l'enfance.</p></div>"},{"i":"3e46499526b0","n":73,"o":"73-4","u":"Définition","t":"Connaître les principaux courants psychothérapeutiques","q":"Quelle est l'hypothèse directrice du courant psychothérapeutique psychodynamique (ou analytique) ?","a":"<div class=\"notion-course\"><p>Le courant psychodynamique postule que les symptômes sont liés à des <strong>conflits inconscients non résolus</strong>, souvent ancrés dans l'histoire du <span class=\"nc-green_bg\">patient</span> (notamment l'enfance, selon les travaux de Freud).</p></div>"},{"i":"4beafcb81798","n":73,"o":"73-4","u":"Définition","t":"Connaître les principaux courants psychothérapeutiques","q":"Quel type de psychothérapie est directement rattaché au courant systémique ?","a":"<div class=\"notion-course\"><ul><li>Thérapie familiale ou systémique.</li><li>Elle explore les interactions et ressources du système ; elle ne prouve pas que la famille est la cause du trouble.</li></ul></div>"},{"i":"6c28e9506323","n":73,"o":"73-4","u":"Définition","t":"Connaître les principaux courants psychothérapeutiques","q":"Qu'est-ce que la psychothérapie de soutien ?","a":"<div class=\"notion-course\"><p>La <span class=\"nc-yellow_bg\">psychothérapie de soutien</span> est une <strong>psychothérapie de 1er niveau</strong>, considérée comme la <strong>base commune</strong> à toutes les autres approches psychothérapeutiques. Elle vise à offrir un cadre d'écoute et de support au <span class=\"nc-green_bg\">patient</span>.</p></div>"},{"i":"b303dd9ccf81","n":73,"o":"73-4","u":"Définition","t":"Connaître les principaux courants psychothérapeutiques","q":"Quelle est l'hypothèse directrice du courant psychothérapeutique systémique ?","a":"<div class=\"notion-course\"><p>Dans le courant systémique, le symptôme est compris comme s'inscrivant dans un <strong>système</strong> (par exemple, la famille ou le couple) en <strong>interaction permanente</strong>, et non comme un problème uniquement individuel.</p></div>"},{"i":"c00a8096a41a","n":73,"o":"73-4","u":"Définition","t":"Connaître les principaux courants psychothérapeutiques","q":"Quelle est l'hypothèse directrice du courant psychothérapeutique cognitivo-comportemental ?","a":"<div class=\"notion-course\"><p>Dans le courant cognitivo-comportemental, les symptômes sont considérés comme des <strong>réponses comportementales et cognitives apprises</strong>. Leur modification passe donc par un processus de <strong>réapprentissage</strong>.</p></div>"},{"i":"0df46cd8ff84","n":73,"o":"73-3","u":"Définition","t":"Connaître les aspects réglementaires","q":"Le titre de psychothérapeute est-il obtenu automatiquement après une formation privée ?","a":"<div class=\"notion-course\"><ul><li>Non : exigences réglementaires de formation, dispenses éventuelles et inscription ; une formation à une technique ne suffit pas.</li></ul></div>"},{"i":"c77bdd88f632","n":73,"o":"73-5","u":"Prise en charge","t":"Connaître les principes communs à toutes les psychothérapies","q":"Quel socle est commun aux psychothérapies ?","a":"<div class=\"notion-course\"><ul><li>Cadre, alliance empathique, engagement, intervention explicative et apprentissages ; objectifs évaluables.</li></ul></div>"},{"i":"ba0d4b7347f6","n":73,"o":"73-6","u":"Prise en charge","t":"Connaître la psychothérapie de soutien","q":"Quel est le but principal d’une psychothérapie de soutien ?","a":"<div class=\"notion-course\"><ul><li>Renforcer les ressources, aider à exprimer les émotions et améliorer l’adaptation à une situation difficile.</li></ul></div>"},{"i":"5e73ea52e5fa","n":73,"o":"73-7","u":"Prise en charge","t":"Connaître les thérapies cognitivo-comportementales","q":"Dans un TOC, quelle technique comportementale est centrale ?","a":"<div class=\"notion-course\"><ul><li>Exposition avec prévention de la réponse, planifiée avec le <span class=\"nc-green_bg\">patient</span>.</li></ul></div>"},{"i":"f59179755998","n":73,"o":"73-8","u":"Prise en charge","t":"Connaître la remédiation cognitive","q":"Remédiation et restructuration cognitives : quelle différence ?","a":"<div class=\"notion-course\"><ul><li>Remédiation : fonctions cognitives et retentissement quotidien. Restructuration : pensées et interprétations dysfonctionnelles.</li></ul></div>"},{"i":"ad0a2e54c37a","n":73,"o":"73-9","u":"Prise en charge","t":"Connaître les principales indications","q":"Quels éléments guident le choix d’une psychothérapie ?","a":"<div class=\"notion-course\"><ul><li>Trouble, gravité, risques, préférences, capacités d’engagement, preuve d’efficacité et disponibilité d’un thérapeute formé.</li></ul></div>"},{"i":"7d0be6e079d9","n":73,"o":"73-3","u":"Définition","t":"Connaître les aspects réglementaires","q":"Faut-il une lettre du médecin pour accéder à Mon soutien psy ?","a":"<div class=\"notion-course\"><ul><li>Non : accès direct possible à un <span class=\"nc-blue_bg\">psychologue</span> partenaire, sous critères d’éligibilité.</li><li>Jusqu’à 12 séances annuelles dans le cas général ; situations particulières à vérifier.</li></ul></div>"}],"courseEdition":{"source":"notion","notionUrl":"https://app.notion.com/p/2ad37f85d94181cb96eaf9cb347e93a5?pvs=204","reviewedAt":"2026-10-14","note":"Cours, cartes et arbres relus. Couleurs des passages Notion correspondants ; références et compléments identifiés dans chaque objectif.","sddStatus":"Situations LiSA vérifiées le 14 octobre 2026 dans la session UNESS connectée.","algorithms":1,"lisaSituations":[{"number":116,"title":"Anxiété","url":"https://livret.uness.fr/lisa/2026/Anxi%C3%A9t%C3%A9_SDD-116","expectations":["Retracer l’histoire, caractériser les symptômes et leur retentissement ; rechercher dépression, suicide et addictions.","Discuter traitement de fond, suivi et avis psychiatrique ; prévenir le mésusage des benzodiazépines."],"verifiedAt":"2026-10-14"},{"number":269,"title":"Suivi et traitement de fond d’un trouble psychiatrique chronique hors dépression","url":"https://livret.uness.fr/lisa/2026/Consultation_de_suivi_et_traitement_de_fond_d%27un_patient_souffrant_d%27un_trouble_psychiatrique_chronique_(hors_d%C3%A9pression)_SDD-269","expectations":["Réévaluer décompensation, risque suicidaire, comorbidités, autonomie et insertion ; surveiller les psychotropes et leur observance.","Expliquer les psychothérapies et coordonner les soins ; la valorisation du stage inclut réhabilitation, remédiation cognitive et démarches MDPH."],"verifiedAt":"2026-10-14"},{"number":288,"title":"Suivi et traitement de fond d’un patient dépressif","url":"https://livret.uness.fr/lisa/2026/Consultation_de_suivi_et_traitement_de_fond_d%27un_patient_d%C3%A9pressif_SDD-288","expectations":["Suivre les symptômes, le fonctionnement, le risque suicidaire, les comorbidités et l’observance.","Informer sur antidépresseur et psychothérapie ; réévaluer les sédatifs et les causes d’une réponse insuffisante."],"verifiedAt":"2026-10-14"}]},"liensGlobaux":[{"href":"https://app.notion.com/p/2ad37f85d94181cb96eaf9cb347e93a5?pvs=204","label":"Ton cours Notion ↗"},{"href":"https://www.asso-aesp.fr/wp-content/uploads/2024/04/EDN-Psychiatrie-et-addictologie-4ed-bd.pdf","label":"CNUP–AESP–CUNEA · Référentiel de psychiatrie et addictologie, 4e édition (2024) ↗"},{"href":"https://www.legifrance.gouv.fr/loda/id/JORFTEXT000022244482/","label":"Légifrance · Décret du 20 mai 2010, titre de psychothérapeute ↗"},{"href":"https://www.ameli.fr/assure/remboursements/rembourse/remboursement-seance-psychologue-mon-soutien-psy","label":"Assurance maladie · Mon soutien psy ↗"}],"arbre":{"rootId":"entry","nodes":[{"id":"entry","kind":"decision","label":"Risque immédiat ou état empêchant le travail psychothérapeutique ?","detail":"<ul><li>Évaluer crise suicidaire, agitation, confusion et épisode sévère.</li></ul>","branches":[{"label":"Oui","to":"urgence"},{"label":"Non","to":"cadre"}]},{"id":"urgence","kind":"urgent","label":"Organiser les soins urgents puis adapter le cadre","detail":"<ul><li>Une psychothérapie ne remplace pas la stabilisation nécessaire.</li></ul>","branches":[]},{"id":"cadre","kind":"decision","label":"Cadre explicite et professionnel qualifié","detail":"<ul><li>Consentement, confidentialité, rythme, coût, objectifs et limites.</li><li>Distinguer titres de psychiatre, psychologue et psychothérapeute.</li></ul>","branches":[{"label":"Besoin de soutien / adaptation","to":"soutien"},{"label":"Symptômes et mécanismes ciblés","to":"structure"},{"label":"Difficultés cognitives et réhabilitation","to":"cognition"}]},{"id":"soutien","kind":"finish","label":"Psychothérapie de soutien","detail":"<ul><li>Alliance, ressources, résolution des difficultés et accompagnement.</li><li>Réévaluer l’indication d’une méthode structurée.</li></ul>","branches":[]},{"id":"structure","kind":"finish","label":"Choisir selon indication, données et préférences","detail":"<ul><li>TCC : formulation, objectifs, exercices et évaluation.</li><li>Autres courants : indications et cadre propres ; aucune méthode universelle.</li></ul>","branches":[]},{"id":"cognition","kind":"finish","label":"Remédiation cognitive intégrée à la réhabilitation","detail":"<ul><li>Évaluer fonctions concernées ; entraînement et transfert dans la vie réelle.</li><li>Associer projet de vie et accompagnement psychosocial.</li></ul>","branches":[]}]}};
